entries[400026] = { ["name"] = "Medaillon des blutroten Kämpfers", ["text"] = "Wirken in 2 sek.\nReagenzien:\nErweckte Zorneskraft (2), Ruhige Tinte (3), Frostige Rune\nOptionale Reagenzien:\nGeringe glorreiche Einsicht (#92) , Löschsand (#249)\nVerkäufer:\nKorganar Qualmschmiede\nZone:\nValdrakken\nKosten:\n3\n\nMedaillon des blutroten Kämpfers\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)Schmuck\n+205 [Beweglichkeit oder Stärke oder Intelligenz] Benutzen: Entfernt alle bewegungseinschränkenden und Kontrollverlusteffekte.\n70\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators" }
entries[400027] = { ["name"] = "Inbrunstinsigne des blutroten Kämpfers", ["text"] = "Wirken in 2 sek.\nReagenzien:\nErweckte Zorneskraft (2), Lodernde Tinte (3), Frostige Rune\nOptionale Reagenzien:\nGeringe glorreiche Einsicht (#92) , Löschsand (#249)\nVerkäufer:\nKorganar Qualmschmiede\nZone:\nValdrakken\nKosten:\n3\n\nInbrunstinsigne des blutroten Kämpfers\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\nErhöht Eure Tempowertung um + 291.\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren Primärwert für 20 Sek. um 457 zu erhöhen.\n70\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators" }
entries[400028] = { ["name"] = "Emblem des blutroten Kämpfers", ["text"] = "Wirken in 2 sek.\nReagenzien:\nErweckte Zorneskraft (2), Blühende Tinte (3), Frostige Rune\nOptionale Reagenzien:\nGeringe glorreiche Einsicht (#92) , Löschsand (#249)\nVerkäufer:\nKorganar Qualmschmiede\nZone:\nValdrakken\nKosten:\n3\n\nEmblem des blutroten Kämpfers\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\n+205 [Beweglichkeit oder Stärke oder Intelligenz] Benutzen: Erhöht 15 Sek. lang die maximale Gesundheit um 26226 . (2 Min Abklingzeit)\n70\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators" }
