entries[400807] = { ["name"] = "Beutel funkelnder Gewürze", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nLangweilige Gewürze\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\nBeutel funkelnder Gewürze\nHandwerkliche Kuriositäten\n\"Die fehlende Zutat war Liebe! Das Aroma ist phänomenal. Ein wunderbarer Geschmack der Verbotenen Insel. Löst womöglich eine besondere Begegnung aus.\"" }
entries[400808] = { ["name"] = "Uralter zeremonieller Dreizack", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nBeschädigter Dreizack\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\nUralter zeremonieller Dreizack\nHandwerkliche Kuriositäten\n\"Dieser Dreizack ist nicht für den Kampf gemacht. Er scheint ritueller Natur zu sein. Passt auf, wo Ihr in auf der Verbotenen Insel ablegt. Löst womöglich eine besondere Begegnung aus.\"" }
entries[400809] = { ["name"] = "Leuchtendes Kristalllesezeichen", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nTrüber Kristall\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\nLeuchtendes Kristalllesezeichen\nHandwerkliche Kuriositäten\n\"Dieses glitzernde Lesezeichen bettelt darum, in ein gutes Buch, wie eines der Verbotenen Insel, gelegt zu werden. Löst womöglich eine besondere Begegnung aus.\"" }
entries[400810] = { ["name"] = "Gnomischer Sprachkasten", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nDefekter gnomischer Sprachkasten\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\nGnomischer Sprachkasten\nHandwerkliche Kuriositäten\n\"Wie kommt Gnomentechnologie auf die Verbotene Insel? Ihr benötigt eine Brummsäule, um sie abzuspielen. Löst womöglich eine besondere Begegnung aus.\"" }
entries[400811] = { ["name"] = "Arkane Bannrune", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nHastig geschriebene Rune\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\nArkane Bannrune\nHandwerkliche Kuriositäten\n\"Nachdem die Linien ausgebessert wurden, ist Euch klar geworden, dass diese Rune Zauberschutze, wie die auf der Verbotenen Insel, bannen soll. Löst womöglich eine besondere Begegnung aus.\"" }
entries[400813] = { ["name"] = "Zeitreibung", ["text"] = "Nutzt die Hitze der chaotischen Zeitlinien während des Ereignisses \"Der Zorn des Sturms\" in der Zukunft der Primalisten, um alle 11 Sek. einen Stapel von ' Eiskalt ' zu entfernen." }
entries[400814] = { ["name"] = "Verstärktes makelloses Leder", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nMakelloser Pelz\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\nVerstärktes makelloses Leder\nHandwerkliche Kuriositäten\n\"Diese Flicken aus verstärktem Leder werden von den Tuskarr von Morqut oft verwendet, um beschädigte Bälge der Verbotenen Insel zu reparieren. Löst womöglich eine besondere Begegnung aus.\"" }
entries[400815] = { ["name"] = "Traditioneller Morqutdrachen", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nZerrissener Morqutdrachen\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\nTraditioneller Morqutdrachen\nHandwerkliche Kuriositäten\n\"Manche sagen, dass an Pfosten geknüpfte Tuskarrdrachen auf der Verbotenen Insel auf den Schwingen des Geistes fliegen. Löst womöglich eine besondere Begegnung aus.\"" }
